lab.solution:
class StudyTargetError(ValueError):
    pass

def daily_target(text):
    try:
        target = int(text)
    except ValueError as error:
        raise StudyTargetError('Daily target must be a whole number.') from error
    if not 1 <= target <= 12:
        raise StudyTargetError('Daily target must be between 1 and 12.')
    return target

for value in ['3', 'zero', '0']:
    try:
        print(daily_target(value))
    except StudyTargetError as error:
        print(f'Fix target: {error}')

lab.testCode:
assert daily_target('3') == 3
for text in ('zero', '0', '13'):
    try:
        daily_target(text)
    except StudyTargetError:
        pass
    else:
        raise AssertionError('invalid target accepted')
